import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount) public {
        // Bound deposit to something reasonable to avoid overflow
        depositAmount = bound(depositAmount, 0, 1e18);
        withdrawAmount = bound(withdrawAmount, 0, 1e18);
        vm.assume(depositAmount >= withdrawAmount);

        // Deploy a reverter callee that will cause the call to fail
        Reverter reverter = new Reverter();
        address caller = address(reverter);

        // Fund the caller and deposit into c
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        (bool ok,) = address(c).call{value: depositAmount}("");
        require(ok, "deposit failed");

        uint256 balanceBefore = c.balances(caller);

        // Perform the withdrawal - it will try to send Ether to the reverter, which will fail
        vm.prank(caller);
        try c.withdraw() {
            // withdrawal did not revert
        } catch {
            // withdrawal did revert
        }

        uint256 balanceAfter = c.balances(caller);

        // General rule: if the balance became zero, Ether must have been transferred successfully.
        // Here the reverter receives no Ether, so its ETH balance is zero. 
        // Therefore, the caller's balance should not be zero after the failed transfer.
        // The buggy version zeros the balance even though the transfer failed.
        assertTrue(!(balanceAfter == 0 && address(caller).balance == 0));
    }
}

