        depositAmount = bound(depositAmount, 1, 1000 ether);
        withdrawAmount = bound(withdrawAmount, 1, depositAmount);

        // Deploy an adversarial callee that always rejects incoming Ether.
        Reverter reverter = new Reverter();
        address caller = address(reverter);

        // Fund the caller and deposit into the contract.
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.f{value: depositAmount}();

        // The caller now has a balance in c, and the caller is the Reverter contract.
        // The Reverter contract attempts to withdraw; its fallback() will revert, causing the low-level call to fail.
        uint256 balanceBefore = c.balances(caller);
        vm.prank(caller);
        c.withdraw();
        uint256 balanceAfter = c.balances(caller);

        // Reference contract: balance unchanged (transfer failed, require failed, balance not zeroed).
        // Mutant: balance zeroed despite transfer failure.
        assertTrue(balanceAfter == balanceBefore);
    }
}

