pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount) public {
        // bound amounts to a wide admissible range, excluding 0 to ensure meaningful state changes
        depositAmount = bound(depositAmount, 1, type(uint128).max);
        withdrawAmount = bound(withdrawAmount, 1, depositAmount);

        // deploy an adversarial reverter that will cause the low-level call in withdraw to fail
        Reverter reverter = new Reverter();
        address reverterAddr = address(reverter);

        // fund the reverter's balance with Ether via deposit through the fallback
        vm.deal(reverterAddr, depositAmount);
        vm.prank(reverterAddr);
        (bool depSuccess, ) = address(c).call{value: depositAmount}("");
        require(depSuccess, "deposit failed");

        // record the reverter's balance right before withdraw
        uint256 balanceBefore = c.balances(reverterAddr);
        require(balanceBefore >= withdrawAmount, "invariant: balance must cover withdrawAmount");

        // attempt a withdrawal that will fail because the Reverter's fallback reverts
        vm.prank(reverterAddr);
        (bool withdrawSuccess, ) = address(c).call(abi.encodeWithSignature("withdraw()"));
        // withdrawSuccess is false because the inner call reverts, but the transaction itself may not revert due to the missing require
        // In the reference contract, the require ensures the whole withdraw reverts; in the mutant it doesn't.
        // So we check balances after.

        uint256 balanceAfter = c.balances(reverterAddr);

        // The property: the balance must equal the balance before (no state change on failed withdrawal)
        // Reference: require reverts whole tx -> balanceBefore == balanceAfter
        // Mutant: no require, zeros balance even on failure -> balanceAfter == 0
        assertTrue(balanceAfter == balanceBefore);
    }
}

contract Reverter {
    // This fallback receives Ether and immediately reverts, causing any low-level call sending Ether to it to fail.
    fallback() external payable {
        revert("Reverter: forced failure");
    }
}

