pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, uint256 reentryAmount) public {
        vm.assume(amount > 0);
        vm.assume(reentryAmount > 0 && reentryAmount <= amount);

        ReentrantAttacker attacker = new ReentrantAttacker();
        vm.deal(address(attacker), amount);

        // fund the contract via fallback on the attacker's behalf
        vm.prank(address(attacker));
        (bool ok, ) = address(c).call{value: amount}("");
        require(ok, "fund failed");

        // attacker's initial balance should be amount
        uint256 initialBalance = c.balances(address(attacker));
        assertEq(initialBalance, amount);

        // invoke withdraw through the attacker; the attacker will reenter on withdraw's external call
        attacker.attack(address(c), reentryAmount);

        // After the transaction completes, read c's balances mapping.
        // The reference (reentrancy-protected) ensures no reentry: the attacker can only withdraw once;
        // the buggy version allows reentry, leaving a non-zero balance.
        uint256 finalBalance = c.balances(address(attacker));
        assertTrue(finalBalance == 0);
    }
}

contract ReentrantAttacker {
    bool private entering;
    uint256 private reentryAmount;
    address private target;

    function attack(address _target, uint256 _reentryAmount) external {
        target = _target;
        reentryAmount = _reentryAmount;
        entering = true;
        C(target).withdraw();
        entering = false;
    }

    receive() external payable {
        if (entering) {
            C(target).withdraw();
        }
    }
}

