pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(amount > 0);

        // Deploy a reentrant attacker that calls withdraw again during its receive
        ReentrantAttacker attacker = new ReentrantAttacker(address(c));
        vm.deal(address(attacker), amount);

        // Record balances before the withdraw
        uint256 balBefore = c.balances(address(attacker));

        // Attacker calls withdraw
        vm.prank(address(attacker));
        c.withdraw();

        // Balances after the withdraw
        uint256 balAfter = c.balances(address(attacker));

        // The rule: no balance can increase after a withdraw (it must be <= before)
        assertTrue(balAfter <= balBefore);
    }
}

contract ReentrantAttacker {
    C target;
    bool private reentered;

    constructor(address _target) payable {
        target = C(_target);
        // Give initial balance to target to allow withdrawal
        (bool ok,) = _target.call{value: msg.value}("");
        require(ok);
    }

    receive() external payable {
        if (!reentered) {
            reentered = true;
            target.withdraw();
        }
    }
}
